#!/usr/bin/env python3
"""A small reimplementation of the observed entr 5.7 command-line behavior.

This implementation is intentionally written from behavioral observations of the
provided executable.  It uses portable polling rather than platform event APIs,
but preserves the user-visible CLI, diagnostics, process execution, and common
watch-loop semantics.
"""

from __future__ import annotations

import errno
import os
import pwd
import signal
import stat as statmod
import subprocess
import sys
import termios
import time
from dataclasses import dataclass
from typing import List, Optional, Tuple

RELEASE = "5.7"
POLL_INTERVAL = 0.05
VALID_OPTIONS = set("acdnprsxz")

USAGE = "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n"
SUMMARY = """summary:
    -a  Do not consolidate events
    -c  Clear screen before execution
    -d  Track files added or removed from directories
    -n  Non-interactive mode
    -p  Wait for first event
    -r  Run as a background process, use signal to restart
    -s  Evaluate using a shell
    -x  Format exit status
    -z  Exit after the utility completes
docs:
    man entr
"""
STATUS_EXAMPLE = """# http://eradman.com/entrproject/status-filters.html
/^signal/ { print $3, "terminated by signal", $2; }
/^exit/ { print $3, "returned exit code", $2; }
"""


class EntrExit(Exception):
    def __init__(self, code: int):
        self.code = code


def progbase() -> str:
    return os.path.basename(sys.argv[0]) or sys.argv[0]


def write_stderr(s: str) -> None:
    sys.stderr.write(s)
    sys.stderr.flush()


def write_stdout(s: str) -> None:
    sys.stdout.write(s)
    sys.stdout.flush()


def print_usage(hint: bool = True) -> None:
    write_stderr(f"release: {RELEASE}\n")
    write_stderr(USAGE)
    if hint:
        write_stderr("hint: use -h to display option summary\n")


def invalid_option(ch: str) -> None:
    write_stderr(f"{sys.argv[0]}: invalid option -- '{ch}'\n")
    print_usage(True)
    raise EntrExit(1)


@dataclass
class Options:
    a: bool = False
    c_count: int = 0
    d_count: int = 0
    n: bool = False
    p: bool = False
    r: bool = False
    s: bool = False
    x_count: int = 0
    z: bool = False


def parse_args(argv: List[str]) -> Tuple[Options, List[str], int]:
    # The observed binary treats a first argument exactly equal to -h as a
    # special help request, even if more arguments follow.  Grouped -h is not
    # accepted.
    if len(argv) >= 2 and argv[1] == "-h":
        write_stdout(SUMMARY)
        print_usage(False)
        raise EntrExit(1)

    opts = Options()
    i = 1
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            i += 1
            break
        if arg == "-" or not arg.startswith("-"):
            break
        # getopt-style short option grouping; --foo is invalid option '-'.
        for ch in arg[1:]:
            if ch not in VALID_OPTIONS:
                invalid_option(ch)
            if ch == "a":
                opts.a = True
            elif ch == "c":
                opts.c_count += 1
            elif ch == "d":
                opts.d_count += 1
            elif ch == "n":
                opts.n = True
            elif ch == "p":
                opts.p = True
            elif ch == "r":
                opts.r = True
            elif ch == "s":
                opts.s = True
            elif ch == "x":
                opts.x_count += 1
            elif ch == "z":
                opts.z = True
        i += 1

    cmd = argv[i:]
    if not cmd:
        print_usage(True)
        raise EntrExit(1)
    if opts.s and len(cmd) != 1:
        write_stderr(f"{progbase()}: -s requires commands to be formatted as a single argument\n")
        raise EntrExit(1)
    return opts, cmd, i


def parse_restart_signal() -> int:
    # Default restart signal is SIGTERM.  When the environment variable is set,
    # the observed Linux build only accepts HUP/INT/QUIT (with optional SIG
    # prefix), despite the documentation listing more names.
    if "ENTR_RESTART_SIGNAL" not in os.environ:
        return signal.SIGTERM
    raw = os.environ.get("ENTR_RESTART_SIGNAL", "")
    shown = raw[3:] if raw.startswith("SIG") else raw
    accepted = {
        "HUP": signal.SIGHUP,
        "INT": signal.SIGINT,
        "QUIT": signal.SIGQUIT,
    }
    if shown in accepted:
        return accepted[shown]
    write_stderr(
        f"{progbase()}: unrecognized signal: {shown} <> (HUP, INT, QUIT, TERM, USR1, USR2)\n"
    )
    raise EntrExit(1)


@dataclass
class Watch:
    path: str
    kind: str              # 'file' or 'dir'
    meta: Optional[Tuple] = None
    entries: Optional[Tuple[str, ...]] = None
    follow: bool = False
    trigger: Optional[str] = None
    parent_watch: bool = False
    filter_hidden: bool = True


def decode_path(raw: bytes) -> str:
    if b"\x00" in raw:
        raw = raw.split(b"\x00", 1)[0]
    return os.fsdecode(raw)


def read_input_paths() -> List[str]:
    data = sys.stdin.buffer.read()
    paths: List[str] = []
    for raw in data.split(b"\n"):
        # split() leaves a final empty element for trailing newline; blank input
        # lines are ignored.  CR is intentionally retained.
        p = decode_path(raw)
        if p == "":
            continue
        paths.append(p)
    return paths


def stat_path(path: str, follow: bool):
    return os.stat(path) if follow else os.lstat(path)


def file_meta(st: os.stat_result) -> Tuple:
    return (
        st.st_dev,
        st.st_ino,
        st.st_mode,
        st.st_size,
        getattr(st, "st_mtime_ns", int(st.st_mtime * 1_000_000_000)),
        getattr(st, "st_ctime_ns", int(st.st_ctime * 1_000_000_000)),
    )


def list_entries(path: str, filter_hidden: bool) -> Tuple[str, ...]:
    names = os.listdir(path)
    if filter_hidden:
        names = [n for n in names if not n.startswith(".")]
    names.sort()
    return tuple(names)


def parent_dir(path: str) -> str:
    d = os.path.dirname(path)
    return d if d else "."


def build_watches(paths: List[str], opts: Options) -> Tuple[List[Watch], bool]:
    follow = "ENTR_FOLLOW_SYMLINK" in os.environ
    watches: List[Watch] = []
    any_valid = False
    # Track parent directories only once per directory.
    parent_dirs = set()
    dir_filter_hidden = opts.d_count < 2

    for path in paths:
        try:
            st = stat_path(path, follow)
        except OSError:
            write_stderr(f"{progbase()}: unable to stat '{path}'\n")
            continue

        mode = st.st_mode
        if statmod.S_ISDIR(mode):
            any_valid = True
            w = Watch(path=path, kind="dir", follow=follow, trigger=path,
                      filter_hidden=dir_filter_hidden)
            w.entries = None
            watches.append(w)
        elif statmod.S_ISREG(mode) or (not follow and statmod.S_ISLNK(mode)):
            any_valid = True
            w = Watch(path=path, kind="file", follow=follow, trigger=path)
            w.meta = file_meta(st)
            watches.append(w)
            if opts.d_count > 0:
                pd = parent_dir(path)
                if pd not in parent_dirs:
                    parent_dirs.add(pd)
                    pw = Watch(path=pd, kind="dir", follow=True, trigger=path,
                               parent_watch=True, filter_hidden=dir_filter_hidden)
                    watches.append(pw)
        else:
            # Non-regular entries such as FIFOs are ignored silently.
            pass

    return watches, any_valid


def initialize_watch_state(watches: List[Watch]) -> bool:
    """Validate event registration and initialize directory snapshots.

    Returns False after printing the observed diagnostic on failure.
    """
    for w in watches:
        if w.kind == "dir":
            try:
                w.entries = list_entries(w.path, w.filter_hidden)
            except OSError:
                write_stderr(f"{progbase()}: unable to open directory: '{w.path}'\n")
                return False
        else:
            # Regular files are opened during registration; unreadable files
            # abort without naming the path.  Symlinks are not followed unless
            # ENTR_FOLLOW_SYMLINK is set.
            try:
                st = stat_path(w.path, w.follow)
                w.meta = file_meta(st)
                if not (not w.follow and statmod.S_ISLNK(st.st_mode)):
                    fd = os.open(w.path, os.O_RDONLY)
                    os.close(fd)
            except PermissionError:
                write_stderr(f"{progbase()}: failed to register VNODE event: Permission denied\n")
                return False
            except IsADirectoryError:
                # Should not happen for a file watch, but match the generic
                # registration failure style rather than a Python traceback.
                write_stderr(f"{progbase()}: failed to register VNODE event: Permission denied\n")
                return False
            except OSError as e:
                # If the path disappeared after stat, the runtime diagnostic is
                # an open failure.
                msg = e.strerror or os.strerror(e.errno or errno.ENOENT)
                write_stderr(f"{progbase()}: cannot open '{w.path}': {msg}\n")
                return False
    return True


def refresh_all_snapshots(watches: List[Watch]) -> None:
    for w in watches:
        try:
            if w.kind == "dir":
                w.entries = list_entries(w.path, w.filter_hidden)
            else:
                w.meta = file_meta(stat_path(w.path, w.follow))
        except OSError:
            # The next polling pass will print the normal diagnostic.
            pass


@dataclass
class Event:
    type: str          # 'file', 'dir', or 'error'
    trigger: str
    code: int = 0
    message: str = ""
    old_meta: Optional[Tuple] = None
    new_meta: Optional[Tuple] = None


def trace_file_event(path: str, old_meta: Optional[Tuple], new_st: os.stat_result) -> None:
    if "EV_TRACE" not in os.environ:
        return
    flags = 0x2
    if old_meta is not None and len(old_meta) >= 3 and old_meta[2] != new_st.st_mode:
        flags = 0x8
    write_stderr(f"0/1: fflags: 0x{flags:x} r {new_st.st_mode:o} {path}\n")


def poll_event(watches: List[Watch]) -> Optional[Event]:
    for w in watches:
        if w.kind == "dir":
            try:
                entries = list_entries(w.path, w.filter_hidden)
            except OSError:
                return Event("error", w.trigger or w.path, 1,
                             f"{progbase()}: unable to open directory: '{w.path}'\n")
            if w.entries is None:
                w.entries = entries
            elif entries != w.entries:
                w.entries = entries
                return Event("dir", w.trigger or w.path, 2)
        else:
            try:
                st = stat_path(w.path, w.follow)
            except OSError as e:
                msg = e.strerror or os.strerror(e.errno or errno.ENOENT)
                return Event("error", w.path, 1,
                             f"{progbase()}: cannot open '{w.path}': {msg}\n")
            meta = file_meta(st)
            if w.meta is None:
                w.meta = meta
            elif meta != w.meta:
                old = w.meta
                w.meta = meta
                trace_file_event(w.path, old, st)
                return Event("file", w.path, 0, old_meta=old, new_meta=meta)
    return None


class StatusFormatter:
    def __init__(self, count: int):
        self.count = count
        self.script: Optional[str] = None
        self.safe_proc: Optional[subprocess.Popen] = None
        if count > 0:
            self.script = self._status_script_path()
            self._ensure_script(self.script)
            if count == 1:
                # The observed environment's awk rejects -S and writes
                # "awk: not an option: -S".  Keep the process object so a later
                # status write can report that it terminated.
                try:
                    self.safe_proc = subprocess.Popen(
                        ["awk", "-S", "-F|", "-f", self.script],
                        stdin=subprocess.PIPE,
                    )
                except OSError:
                    self.safe_proc = None

    def _status_script_path(self) -> str:
        if "ENTR_STATUS_SCRIPT" in os.environ:
            return os.environ["ENTR_STATUS_SCRIPT"]
        try:
            home = pwd.getpwuid(os.getuid()).pw_dir
        except Exception:
            home = os.environ.get("HOME", ".")
        return os.path.join(home, ".entr", "status.awk")

    def _ensure_script(self, path: str) -> None:
        if os.path.exists(path):
            return
        d = os.path.dirname(path)
        if d and not os.path.exists(d):
            os.makedirs(d, mode=0o750, exist_ok=True)
            try:
                os.chmod(d, 0o750)
            except OSError:
                pass
        with open(path, "w", encoding="utf-8") as f:
            f.write(STATUS_EXAMPLE)
        try:
            os.chmod(path, 0o640)
        except OSError:
            pass
        write_stdout(f"entr: created '{path}'\n")

    def wait_safe_quietly(self) -> None:
        if self.safe_proc is not None:
            try:
                self.safe_proc.wait(timeout=0.05)
            except subprocess.TimeoutExpired:
                pass

    def close(self) -> None:
        if self.safe_proc is not None:
            try:
                if self.safe_proc.stdin:
                    self.safe_proc.stdin.close()
            except Exception:
                pass
            try:
                self.safe_proc.wait(timeout=0.2)
            except Exception:
                try:
                    self.safe_proc.terminate()
                except Exception:
                    pass

    def report(self, returncode: int, util_name: str) -> bool:
        """Report child status.  Return True if the status process died.

        A True return matches the observed -x behavior: print a diagnostic and
        terminate entr with status 0.
        """
        if self.count <= 0:
            return False
        if returncode < 0:
            line = f"signal|{-returncode}|{util_name}\n"
        else:
            line = f"exit|{returncode}|{util_name}\n"

        if self.count == 1:
            proc = self.safe_proc
            if proc is None or proc.poll() is not None or proc.stdin is None:
                write_stderr(f"{progbase()}: status process terminated\n")
                return True
            try:
                proc.stdin.write(line.encode())
                proc.stdin.flush()
            except Exception:
                write_stderr(f"{progbase()}: status process terminated\n")
                return True
            if proc.poll() is not None:
                write_stderr(f"{progbase()}: status process terminated\n")
                return True
            return False

        # -xx: shell commands/redirection are permitted by the original by
        # invoking awk without safe mode.  Run awk for each status line; this
        # preserves the visible output for the documented filters.
        try:
            subprocess.run(["awk", "-F|", "-f", self.script or ""],
                           input=line.encode(), check=False)
        except OSError as e:
            write_stderr(f"awk: {e.strerror}\n")
        return False


@dataclass
class ChildResult:
    returncode: int
    util_name: str


def child_environment() -> dict:
    env = os.environ.copy()
    if "PAGER" not in env:
        env["PAGER"] = "/bin/cat"
    return env


def status_name_from_cmd(cmd: List[str]) -> str:
    if not cmd:
        return ""
    b = os.path.basename(cmd[0])
    return b if b else cmd[0]


def replace_underscore(args: List[str], current_file: str) -> List[str]:
    out = list(args)
    for i, a in enumerate(out):
        if a == "/_":
            out[i] = current_file
            break
    return out


def build_command(opts: Options, user_cmd: List[str], current_file: str) -> Tuple[List[str], str]:
    if opts.s:
        if "SHELL" in os.environ:
            shell = os.environ.get("SHELL", "")
        else:
            shell = "/bin/sh"
        cmd = [shell, "-c", user_cmd[0], current_file]
        return cmd, status_name_from_cmd([shell])
    cmd = replace_underscore(user_cmd, current_file)
    return cmd, status_name_from_cmd(cmd)


def clear_screen(count: int) -> None:
    if count <= 0:
        return
    if count == 1:
        write_stdout("\033[2J\033[H")
    else:
        write_stdout("\033[2J\033[3J\033[H")


def start_process(opts: Options, user_cmd: List[str], current_file: str,
                  persistent: bool = False) -> Tuple[Optional[subprocess.Popen], Optional[ChildResult]]:
    clear_screen(opts.c_count)
    cmd, util_name = build_command(opts, user_cmd, current_file)
    env = child_environment()

    if not cmd or cmd[0] == "":
        shown = cmd[0] if cmd else ""
        write_stderr(f"{progbase()}: exec {shown}: No such file or directory\n")
        return None, ChildResult(1, util_name)

    try:
        p = subprocess.Popen(cmd, env=env, start_new_session=persistent)
        return p, None
    except OSError as e:
        if e.errno == errno.ENOEXEC and not opts.s:
            # execvp(3) falls back to /bin/sh for executable text files with no
            # recognized header.
            try:
                fallback = ["/bin/sh", cmd[0]] + cmd[1:]
                p = subprocess.Popen(fallback, env=env, start_new_session=persistent)
                return p, None
            except OSError as e2:
                e = e2
        msg = e.strerror or os.strerror(e.errno or errno.ENOENT)
        # Linux returns EACCES for attempting to exec a directory; the observed
        # diagnostic prints Permission denied.
        write_stderr(f"{progbase()}: exec {cmd[0]}: {msg}\n")
        return None, ChildResult(1, util_name)


def wait_process(p: subprocess.Popen) -> int:
    while True:
        try:
            return p.wait(timeout=0.05)
        except subprocess.TimeoutExpired:
            if interrupted:
                # Leave actual child cleanup to the caller when needed.
                continue


def normalized_status(rc: int) -> int:
    return 128 + (-rc) if rc < 0 else rc


interrupted = False


def on_sigint(signum, frame):  # noqa: D401
    global interrupted
    interrupted = True


def setup_tty_if_needed(opts: Options):
    if opts.n:
        return None
    try:
        fd = os.open("/dev/tty", os.O_RDONLY | os.O_NONBLOCK)
        # The diagnostic observed in non-tty environments comes from failing to
        # get terminal attributes, so perform that call explicitly.
        old = termios.tcgetattr(fd)
        return (fd, old)
    except Exception:
        write_stderr(f"{progbase()}: unable to get terminal attributes, use '-n' to run non-interactively\n")
        raise EntrExit(1)


def restore_tty(tty_state) -> None:
    if tty_state is None:
        return
    fd, old = tty_state
    try:
        termios.tcsetattr(fd, termios.TCSANOW, old)
    except Exception:
        pass
    try:
        os.close(fd)
    except Exception:
        pass


def read_tty_command(tty_state) -> Optional[str]:
    if tty_state is None:
        return None
    fd, _ = tty_state
    try:
        import select
        r, _, _ = select.select([fd], [], [], 0)
        if not r:
            return None
        data = os.read(fd, 16)
    except Exception:
        return None
    for b in data:
        if b == ord('q'):
            return 'q'
        if b == ord(' '):
            return 'space'
    return None


def run_once(opts: Options, user_cmd: List[str], current_file: str,
             formatter: StatusFormatter, persistent: bool = False) -> Tuple[int, str, bool]:
    p, immediate = start_process(opts, user_cmd, current_file, persistent=persistent)
    if immediate is not None:
        died = formatter.report(immediate.returncode, immediate.util_name)
        return immediate.returncode, immediate.util_name, died
    assert p is not None
    rc = wait_process(p)
    util_name = build_command(opts, user_cmd, current_file)[1]
    died = formatter.report(rc, util_name)
    return rc, util_name, died


def terminate_process_group(p: subprocess.Popen, sig: int) -> int:
    if p.poll() is not None:
        return p.returncode
    try:
        os.killpg(p.pid, sig)
    except Exception:
        try:
            p.terminate()
        except Exception:
            pass
    # Wait for the process to release resources.  The original waits for child
    # termination before restarting.
    deadline = time.time() + 5.0
    while time.time() < deadline:
        rc = p.poll()
        if rc is not None:
            return rc
        time.sleep(0.02)
    try:
        os.killpg(p.pid, signal.SIGKILL)
    except Exception:
        pass
    try:
        return p.wait(timeout=1)
    except Exception:
        return -signal.SIGKILL


def wait_for_event(watches: List[Watch], tty_state=None) -> Event:
    global interrupted
    while True:
        if interrupted:
            interrupted = False
            return Event("interrupt", "", 0)
        cmd = read_tty_command(tty_state)
        if cmd == 'q':
            return Event("interrupt", "", 0)
        if cmd == 'space':
            # Manual runs use the default current file (first watch trigger).
            trig = watches[0].trigger if watches else ""
            return Event("file", trig or "", 0)
        ev = poll_event(watches)
        if ev is not None:
            return ev
        time.sleep(POLL_INTERVAL)


def handle_event_before_run(ev: Event) -> Optional[int]:
    if ev.type == "interrupt":
        return 0
    if ev.type == "error":
        write_stderr(ev.message)
        return ev.code
    return None


def normal_loop(opts: Options, user_cmd: List[str], watches: List[Watch],
                formatter: StatusFormatter, tty_state) -> int:
    current_file = watches[0].trigger if watches else ""

    if not opts.p:
        rc, _name, died = run_once(opts, user_cmd, current_file or "", formatter, False)
        if died:
            return 0
        if opts.z:
            return normalized_status(rc)
        # Default behavior consolidates/ignores events generated while the child
        # was running.
        if not opts.a:
            refresh_all_snapshots(watches)

    while True:
        ev = wait_for_event(watches, tty_state)
        pre = handle_event_before_run(ev)
        if pre is not None:
            return pre
        current_file = ev.trigger or current_file or ""
        rc, _name, died = run_once(opts, user_cmd, current_file, formatter, False)
        if died:
            return 0
        if ev.type == "dir":
            write_stderr(f"{progbase()}: directory altered\n")
            return 2
        if opts.z:
            return normalized_status(rc)
        if not opts.a:
            refresh_all_snapshots(watches)


def wait_child_with_events(p: subprocess.Popen, watches: List[Watch], opts: Options,
                           tty_state) -> Tuple[Optional[Event], int]:
    """Wait for a persistent child, optionally collecting events for -a/-r.

    Returns (event, child_returncode).  event is set when a restart/quit/error
    condition occurs before natural child exit.
    """
    global interrupted
    pending: Optional[Event] = None
    while True:
        rc = p.poll()
        if rc is not None:
            return pending, rc
        if interrupted:
            interrupted = False
            return Event("interrupt", "", 0), 0
        cmd = read_tty_command(tty_state)
        if cmd == 'q':
            return Event("interrupt", "", 0), 0
        if cmd == 'space':
            return Event("file", watches[0].trigger if watches else "", 0), 0
        ev = poll_event(watches)
        if ev is not None:
            # -r restarts on file-system events; -a has no special effect in
            # persistent mode, matching the documentation.
            return ev, 0
        time.sleep(POLL_INTERVAL)


def persistent_loop(opts: Options, user_cmd: List[str], watches: List[Watch],
                    formatter: StatusFormatter, tty_state, restart_sig: int) -> int:
    current_file = watches[0].trigger if watches else ""

    child: Optional[subprocess.Popen] = None
    child_util = ""

    def start_current() -> Tuple[Optional[subprocess.Popen], Optional[int], str, bool]:
        p, immediate = start_process(opts, user_cmd, current_file or "", persistent=True)
        util = build_command(opts, user_cmd, current_file or "")[1]
        if immediate is not None:
            died = formatter.report(immediate.returncode, immediate.util_name)
            return None, immediate.returncode, immediate.util_name, died
        return p, None, util, False

    if not opts.p:
        child, immediate_rc, child_util, died = start_current()
        if died:
            return 0
        if immediate_rc is not None and opts.z:
            return normalized_status(immediate_rc)

    while True:
        if child is None:
            ev = wait_for_event(watches, tty_state)
            pre = handle_event_before_run(ev)
            if pre is not None:
                return pre
            current_file = ev.trigger or current_file or ""
            child, immediate_rc, child_util, died = start_current()
            if died:
                return 0
            if ev.type == "dir":
                if child is not None:
                    rc = wait_process(child)
                    formatter.report(rc, child_util)
                write_stderr(f"{progbase()}: directory altered\n")
                return 2
            if immediate_rc is not None:
                if opts.z:
                    return normalized_status(immediate_rc)
                child = None
            continue

        ev, natural_rc = wait_child_with_events(child, watches, opts, tty_state)
        if ev is None:
            # The persistent utility exited on its own.  It is not restarted
            # until another event, unless -z asks entr to exit immediately.
            died = formatter.report(natural_rc, child_util)
            if died:
                return 0
            child = None
            if opts.z:
                return normalized_status(natural_rc)
            continue

        pre = handle_event_before_run(ev)
        if pre is not None:
            if ev.type == "interrupt":
                terminate_process_group(child, restart_sig)
            return pre

        # A file or keyboard event restarts the persistent child.
        terminate_process_group(child, restart_sig)
        current_file = ev.trigger or current_file or ""
        child, immediate_rc, child_util, died = start_current()
        if died:
            return 0
        if ev.type == "dir":
            if child is not None:
                rc = wait_process(child)
                formatter.report(rc, child_util)
            write_stderr(f"{progbase()}: directory altered\n")
            return 2
        if immediate_rc is not None:
            if opts.z:
                return normalized_status(immediate_rc)
            child = None


def main(argv: List[str]) -> int:
    global interrupted
    signal.signal(signal.SIGINT, on_sigint)

    try:
        opts, user_cmd, _ = parse_args(argv)
        restart_sig = parse_restart_signal()

        formatter = StatusFormatter(opts.x_count)

        if "EV_TRACE" in os.environ:
            try:
                open_max = os.sysconf("SC_OPEN_MAX")
            except Exception:
                open_max = 1024
            write_stderr(f"open_max: {open_max}\n")

        paths = read_input_paths()
        watches, any_valid = build_watches(paths, opts)
        if not any_valid:
            write_stderr(f"{progbase()}: No regular files to watch\n")
            # If -x started an unsupported safe awk, allow its diagnostic to be
            # emitted, but do not add "status process terminated" in this path.
            formatter.wait_safe_quietly()
            return 1

        if not initialize_watch_state(watches):
            formatter.wait_safe_quietly()
            return 1

        tty_state = setup_tty_if_needed(opts)
        try:
            if opts.r:
                code = persistent_loop(opts, user_cmd, watches, formatter, tty_state, restart_sig)
            else:
                code = normal_loop(opts, user_cmd, watches, formatter, tty_state)
        finally:
            restore_tty(tty_state)
            formatter.close()
        return code
    except EntrExit as e:
        return e.code


if __name__ == "__main__":
    sys.exit(main(sys.argv))
